package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class SubtractionPatternsTest {
 @Test public void visibleRelationsIgnoreStoredKeys(){Checker c=new Checker();for(int a:new int[]{100,200,300,400,500})for(int b=1;b<=99;b++)for(int step:new int[]{10,100,-10,-100}){if(a+2*step<100||a+2*step>500)continue;Question q=SubtractionPatterns.make(a,b,step);q.answers=new String[]{"0","0"};q.expression="poison";assertTrue(c.check(q,List.of(),List.of(""+(a+step-b),""+(a+2*step-b))).correct());assertEquals(1,c.check(q,List.of(),List.of(""+(a+step-b),"0")).index);q.prompt=q.prompt.replace(" = "+(a-b)+"\n"," = 0\n");assertNull(SubtractionPatterns.read(q));}}
 @Test public void freshAndScoped(){Generator g=new Generator(new Random(216));List<String> recent=new ArrayList<>();for(int i=0;i<1188;i++){Question q=g.next(SubtractionPatterns.ID,recent,false,CurriculumLimits.NONE);assertNotNull(SubtractionPatterns.read(q));assertFalse(recent.contains(q.signature()));recent.add(q.signature());}Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,"na-nied-primary-2024-v1");assertTrue(GlobalCurriculum.pack(p).inGrade(SubtractionPatterns.ID,3));assertFalse(GlobalCurriculum.pack(p).inGrade(SubtractionPatterns.ID,2));GlobalCurriculum.chooseCountry(p,"AQ");assertFalse(GlobalCurriculum.available(p).stream().anyMatch(s->SubtractionPatterns.supports(s.id)));}
}
